<?php
require __DIR__ . '/../config/config.php';
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$userStmt=db()->prepare('SELECT * FROM users WHERE id=? LIMIT 1');$userStmt->execute([$_SESSION['user_id']]);$user=$userStmt->fetch();
$orderStmt=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$orderStmt->execute([$_SESSION['user_id']]);$orders=$orderStmt->fetchAll();
$counts=['total'=>count($orders),'pending'=>0,'completed'=>0,'cancelled'=>0];foreach($orders as $o){if($o['status']==='delivered')$counts['completed']++;elseif($o['status']==='cancelled')$counts['cancelled']++;else $counts['pending']++;}
?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User Dashboard</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="topbar"><div class="brand-wrap"><div class="logo-circle">G</div><strong><?=e(setting('site_name','GadgetMart'))?></strong></div><div class="header-right"><a href="../index.php">হোম</a><a href="../products.php">শপ</a><a href="logout.php">লগআউট</a></div></header><main class="page-shell"><section class="user-profile"><div><h2>স্বাগতম, <?=e($user['name'])?></h2><p><?=e($user['email'])?></p></div><a class="btn" href="../products.php">আরও শপ করুন</a></section><div class="stats-grid"><div class="stat-card"><span>মোট অর্ডার</span><strong><?=e($counts['total'])?></strong></div><div class="stat-card"><span>চলমান</span><strong><?=e($counts['pending'])?></strong></div><div class="stat-card"><span>সম্পন্ন</span><strong><?=e($counts['completed'])?></strong></div><div class="stat-card"><span>বাতিল</span><strong><?=e($counts['cancelled'])?></strong></div></div><section class="panel"><h3>অর্ডার ইতিহাস</h3><?php if(!$orders):?><div class="alert success">এখনো কোনো অর্ডার নেই।</div><?php else:?><div class="table-wrap"><table><tr><th>অর্ডার</th><th>তারিখ</th><th>মোট</th><th>স্ট্যাটাস</th><th>ডিটেইল</th></tr><?php foreach($orders as $o):?><tr><td>#<?=e($o['id'])?></td><td><?=e($o['created_at'])?></td><td>৳<?=e(number_format((float)$o['total'],2))?></td><td><span class="status-badge status-<?=e($o['status'])?>"><?=e($o['status'])?></span></td><td><a class="btn btn-secondary" href="order_detail.php?id=<?=e($o['id'])?>">দেখুন</a></td></tr><?php endforeach;?></table></div><?php endif;?></section></main></body></html>
